struct sk_buff *fragment_udp_ipv6_packet(struct sk_buff *skb, u32 features)
{
    if (!skb || skb->len <= MSS)
        return ERR_PTR(-EINVAL);

    if (skb->protocol != htons(ETH_P_IPV6))
        return ERR_PTR(-EPROTO);

    if (skb_checksum_help(skb))
        return ERR_PTR(-EPROTO);

    skb_reset_transport_header(skb);
    skb_set_network_header(skb, sizeof(struct ipv6hdr));
    skb->protocol = htons(ETH_P_IPV6);

    if (skb_segment(skb, features))
        return ERR_PTR(-ENOMEM);

    return skb;
}

struct sk_buff *fragment_udp_ipv6_packet(struct sk_buff *skb, u32 features)
{
    struct ipv6hdr *ipv6h;
    struct udphdr *udph;
    int mss = skb->dev->mtu - sizeof(struct ipv6hdr) - sizeof(struct udphdr);
    struct sk_buff *segs = NULL;

    if (skb->len <= mss)
        return skb;

    if (!(features & NETIF_F_SG)) {
        return ERR_PTR(-EINVAL);
    }

    ipv6h = ipv6_hdr(skb);
    udph = udp_hdr(skb);

    udph->check = 0;

    skb_reset_network_header(skb);
    skb_set_transport_header(skb, sizeof(*ipv6h));

    segs = ip6_fragment(skb, features, NULL);
    if (IS_ERR(segs))
        return segs;

    skb = segs;
    while (skb) {
        struct sk_buff *next = skb->next;
        struct udphdr *frag_udph = udp_hdr(skb);

        frag_udph->check = 0;
        frag_udph->check = csum_ipv6_magic(&ipv6h->saddr, &ipv6h->daddr, skb->len - sizeof(*ipv6h) - sizeof(*udph), IPPROTO_UDP, skb_checksum(skb, sizeof(*ipv6h) + sizeof(*udph), 0));

        skb = next;
    }

    return segs;
}

struct sk_buff *fragment_udp_packet(struct sk_buff *skb, u32 features) {
    int mss = skb->dev->mtu - sizeof(struct ipv6hdr) - sizeof(struct udphdr);
    struct udphdr *uh = udp_hdr(skb);

    if (skb->len <= mss)
        return skb;

    if (features & NETIF_F_NO_CSUM) {
        return ERR_PTR(-EINVAL);
    }

    skb_reset_transport_header(skb);
    skb_set_transport_header(skb, sizeof(struct udphdr));
    uh = udp_hdr(skb);
    uh->check = 0;
    uh->check = csum_tcpudp_nofold(ipv6_hdr(skb)->saddr, ipv6_hdr(skb)->daddr,
                                    skb->len, IPPROTO_UDP, skb_checksum(skb));

    skb = skb_share_check(skb, GFP_ATOMIC);
    if (!skb)
        return ERR_PTR(-ENOMEM);

    if (skb_segment(skb, features)) {
        return ERR_PTR(-EINVAL);
    }

    return skb;
}

struct sk_buff *fragment_udp_packet(struct sk_buff *skb, u32 features)
{
    int mss = skb->dev ? skb->dev->mtu - sizeof(struct ipv6hdr) - sizeof(struct udphdr) : 0;

    if (skb->len <= mss)
        return skb;

    if (!skb_is_gso(skb)) {
        return ERR_PTR(-EINVAL);
    }

    skb_checksum_help(skb);

    skb_push(skb, sizeof(struct ipv6hdr));
    skb_pull(skb, sizeof(struct udphdr));

    skb = ip6_fragment(skb, features);

    if (IS_ERR(skb)) {
        return skb;
    }

    return skb;
}
